    {
      "foundation": "care",
      "basis": "Issue salience on living costs (19.7%), health (7.0%), and poverty/inequality (~2.4% combined).",
      "status": "SCORED",
      "weight": 0.22
    },
    {
      "foundation": "loyalty",
      "basis": "High immigration salience (17%), mild Euroscepticism on EU integration (mean 4.73), and some attention to defence/war.",
      "status": "SCORED",
      "weight": 0.20
    },
    {
      "foundation": "authority",
      "basis": "Derived authority-liberty mean 6.2 (more authoritarian) plus salience for crime/defence/terrorism.",
      "status": "SCORED",
      "weight": 0.30
    },
    {
      "foundation": "sanctity",
      "basis": "No direct purity items; 'morals' (0.3%) and gender/sexuality/family (0.1%) are minimal.",
      "status": "INSUFFICIENT",
      "weight": null
    },
    {
      "foundation": "equality",
      "basis": "Redistribution placement mean 4.68 (slightly below midpoint) alongside inequality/poverty salience.",
      "status": "SCORED",
      "weight": 0.10
    },
    {
      "foundation": "proportionality",
      "basis": "Slight rightward self-placement (4.74) and lower redistribution support (4.68), with small salience for taxation/debt/welfare.",
